def three_colorable(adj):
    # backtrack
    order=sorted(range(n), key=lambda x: -len(adj[x]))
    colors=[-1]*n
    def bt(i):
        if i==n: return True
        v=order[i]
        used={colors[w] for w in adj[v] if colors[w]!=-1}
        for c in range(3):
            if c not in used:
                colors[v]=c
                if bt(i+1): return True
                colors[v]=-1
        return False
    return bt(0)

def find_coloring(adj):
    order=sorted(range(n), key=lambda x: -len(adj[x]))
    colors=[-1]*n
    def bt(i):
        if i==n: return colors[:]
        v=order[i]
        used={colors[w] for w in adj[v] if colors[w]!=-1}
        for c in range(3):
            if c not in used:
                colors[v]=c
                r=bt(i+1)
                if r: return r
                colors[v]=-1
        return None
    return bt(0)

