from itertools import combinations, permutations
from pysat.solvers import Solver
from pysat.card import CardEnc, EncType
import time

def solve_partition(sizes):
    n=sum(sizes)
    colors=[]
    for c,s in enumerate(sizes): colors += [c]*s
    allowed=[(i,j) for i,j in combinations(range(n),2) if colors[i]!=colors[j]]
    var={e:k+1 for k,e in enumerate(allowed)}
    def get(u,v):
        if u>v: u,v=v,u
        return var.get((u,v))
    clauses=[]; cyc_count=0
    for k in range(3,7):
        for S in combinations(range(n),k):
            st=S[0]
            for perm in permutations(S[1:]):
                cyc=(st,)+perm
                if cyc[1]>cyc[-1]: continue
                lits=[]; ok=True
                for i in range(k):
                    e=get(cyc[i],cyc[(i+1)%k])
                    if e is None:
                        ok=False; break
                    lits.append(-e)
                if ok:
                    clauses.append(lits); cyc_count+=1
    cnf=CardEnc.atleast(lits=list(range(1,len(allowed)+1)), bound=19, encoding=EncType.seqcounter, top_id=len(allowed))
    allc=clauses+cnf.clauses
    with Solver(name='glucose3', bootstrap_with=allc) as s:
        sat=s.solve()
        if sat:
            m=set(l for l in s.get_model() if l>0)
            es=[e for e in allowed if var[e] in m]
            return es, len(allowed), cyc_count, len(allc)
    return None, len(allowed), cyc_count, len(allc)

